// ---------------------------------------------------------------------------

export const beginUnitTest = (
		url: string
		): [string, (lStrings: TemplateStringsArray) => string] => {

	debugger
	initLogLevel('testing')

	const {dir, stub} = parsePath(url)
	const name = stub.split('.')[0]
	const root = mkpath(relative(Deno.cwd(), dir), name)
	return [root, (lStrings: TemplateStringsArray): string => {
		const str = lStrings[0]
		return (str === '') ? root : `${root}/${str}`
	}
		]
}

