export const line = (n: number): string => {

	return '---> ' + n.toString()
}

// ---------------------------------------------------------------------------

export const getTestName = (): string => {

	debugger
	const frame = getMyOutsideCaller()
	const name = defined(frame) ? `line ${frame.line}` : "line ?"
	return name
}

// ---------------------------------------------------------------------------

export const equal = (
		value: unknown,
		expected: unknown,
		name?: string
		): void => {

	if (isString(value) && isString(expected)) {
		Deno.test(name || getTestName(), () => {
			assertEquals(rtrim(value), rtrim(expected))
		})
	}
	else {
		Deno.test(name || getTestName(), () => {
			assertEquals(value, expected)
		})
	}
	return
}

// ---------------------------------------------------------------------------

export const truthy = (
		value: unknown,
		name?: string
		): void => {

	Deno.test(name || getTestName(), () => {
		assert(value)
	})
	return
}

// ---------------------------------------------------------------------------

export const falsy = (
		value: unknown,
		name?: string
		): void => {

	Deno.test(name || getTestName(), () => {
		assert((!value))
	})
	return
}

