// HYBRID

export const succeeds = (
	func: TVoidFunc,
	name?: string
	): void => {

	const testName = name || getTestName()
	Deno.test(testName, () => {
		func()
		assert(true)
		return
	})
	return
}

// ---------------------------------------------------------------------------
// HYBRID

export const fails = (
	func: TVoidFunc | TAsyncVoidFunc,
	name?: string
	): void => {

	const testName = name || getTestName()
	if (isAsyncFunction(func)) {
		Deno.test(testName, async () => {
			await assertRejects(async () => {
				await func()
				return
			})
		})
	}
	else {
		Deno.test(testName, () => {
			assertThrows(() => {
				const result = func()
				return
			})
		})
	}
	return
}

