// --- Returns a function that, when called, returns a promise

export const mockAsyncTask = <T=unknown,>(
		value: T,
		ms: number = 10,
		errMsg: (string | undefined) = undef
		): () => Promise<T> => {

	return () => {
		return new Promise<T>(async (resolve, reject) => {
			DBG(`START TASK ${value}`)
			await sleep(ms)
			DBG(`END TASK ${value}`)
			if (defined(errMsg)) {
				reject(new Error(errMsg))
			}
			else {
				resolve(value)
			}
		})
	}
}

// ---------------------------------------------------------------------------
// --- Returns a function that, when called, returns a promise

export const mockPromise = <T=unknown,>(
		value: T,
		ms: number = 10,
		errMsg: (string | undefined) = undef
		): Promise<T> => {

	return new Promise<T>(async (resolve, reject) => {
		DBG(`START TASK ${value}`)
		await sleep(ms)
		DBG(`END TASK ${value}`)
		if (defined(errMsg)) {
			reject(new Error(errMsg))
		}
		else {
			resolve(value)
		}
	})
}

// ---------------------------------------------------------------------------

export const utTableHeader = (): string => {

	return f`${'OK'}:4  ${'Fail'}:4  ${'secs.'}:6  Stub`
}

// ---------------------------------------------------------------------------

export const utTableSep = (): string => {

	return '-'.repeat(24)
}

// ---------------------------------------------------------------------------

const fmtRow = (
		nOK: integer,
		nBad: integer,
		secs: string,
		stub: string
		): string => {

	const okStr  = (nOK === 0)  ? colorize(nOK, 'red')    : colorize(nOK, 'green')
	const badStr = (nBad === 0) ? colorize(nBad, 'green') : colorize(nBad, 'red')
	return f`${okStr}:4  ${badStr}:4  ${secs}:6  ${stub}`
}

// ---------------------------------------------------------------------------

const fmtError = (
		errMsg: string,
		stub: string
		): string => {

	return f`${errMsg}:{red} ${stub}`
}

// ---------------------------------------------------------------------------

export const utTableRow = (h: TExecResult): string => {

	const {success, notNeeded, infile, stdout} = h
	assert(defined(infile), "No infile in hResult")
	const {stub} = parsePath(infile)
	if (notNeeded) {
		return fmtError('Missing Unit Test', stub)
	}
	if (notdefined(stdout)) {
		console.log("EXEC RESULT:")
		console.log(h)
		console.log('-'.repeat(64))
		return fmtError('No STDOUT', stub)
	}
	const lMatches = decolorize(stdout).match(/(\d+)\s+passed\s+\|\s+(\d+)\s+failed\s+\((\d+\w+)\)/)
	if (defined(lMatches)) {
		const [_, nOK, nBad, timeTaken] = lMatches
		return fmtRow(parseInt(nOK), parseInt(nBad), timeTaken, stub)
	}
	else {
		return fmtError(`NO MATCH:\n${stdout}`, stub)
	}
}

